const projects = await api('/api/projects');
const renderProjects = () => {
  list.replaceChildren();
  for (const project of projects.filter(p => Boolean(p.archived) === (projectFilter.value === 'Archived'))) {
    const row = element('div', undefined, 'project-row'); row.dataset.testid = 'project-row';
    row.append(element('span', project.name, 'project-name'));
    const summary = element('span', `${project.completedCount}/${project.totalCount} completed`); summary.dataset.testid = 'project-summary'; row.append(summary);
    const open = element('button', 'Open project'); open.type = 'button';
    open.addEventListener('click', () => { history.pushState({}, '', `/projects/${project.id}`); showProject(project); });
    row.append(open);
    const action = element('button', project.archived ? 'Restore project' : 'Archive project'); action.type = 'button';
    action.addEventListener('click', async () => { await api(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' }); showList(); });
    row.append(action); list.append(row);
  }
};
projectFilter.addEventListener('change', renderProjects); renderProjects();

